public Node cloneGraph(Node node) {
    if (node == null) return null;
    Map<Node, Node> clones = new HashMap<>();
    clones.put(node, new Node(node.val));
    Queue<Node> q = new LinkedList<>();
    q.offer(node);
    while (!q.isEmpty()) {
        Node u = q.poll();
        for (Node nb : u.neighbors) {
            if (!clones.containsKey(nb)) {
                clones.put(nb, new Node(nb.val));
                q.offer(nb);
            }
            clones.get(u).neighbors.add(clones.get(nb));
        }
    }
    return clones.get(node);
}

code.python:
from collections import deque

def cloneGraph(self, node: 'Node') -> 'Node':
    if node is None:
        return None
    clones: dict['Node', 'Node'] = {node: Node(node.val)}
    q = deque([node])
    while q:
        u = q.popleft()
        for nb in u.neighbors:
            if nb not in clones:
                clones[nb] = Node(nb.val)
                q.append(nb)
            clones[u].neighbors.append(clones[nb])
    return clones[node]

